var pts = new List<double[]>();
foreach (var o in (object[])args["points"]) { var a = (object[])o; pts.Add(new[]{ Convert.ToDouble(a[0]), Convert.ToDouble(a[1]) }); }
var pl = doc.ActiveProjectLocation;
var tf = pl.GetTotalTransform();
var res = pts.Select((p,i) => {
  var s = new XYZ(p[0]/0.3048, p[1]/0.3048, 0);
  var c = tf.OfPoint(s); // candidate internal
  var back = tf.Inverse.OfPoint(c);
  var pp = pl.GetProjectPosition(new XYZ(c.X, c.Y, 0));
  // reconstruct shared from internal using project position of origin as check
  return new { pt = "P0"+(i+1), internalX_m = Math.Round(c.X*0.3048,4), internalY_m = Math.Round(c.Y*0.3048,4), roundTripE = Math.Round(back.X*0.3048,3), roundTripN = Math.Round(back.Y*0.3048,3) };
}).ToList();
// independent check: survey/base point shared report via ProjectLocation transform of origin
var originShared = tf.Inverse.OfPoint(XYZ.Zero);
return new { points = res, originToShared_E = Math.Round(originShared.X*0.3048,4), originToShared_N = Math.Round(originShared.Y*0.3048,4), tfOrigin_m = new { x = Math.Round(tf.Origin.X*0.3048,3), y = Math.Round(tf.Origin.Y*0.3048,3) } };
